<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg: #0A0A0A;
  --bg-card: #141414;
  --bg-card-hover: #1a1a1a;
  --fg: #FFFFFF;
  --fg-muted: #999999;
  --fg-dim: #666666;
  --accent: #4A9EFF;
  --accent-warm: #E8A838;
  --border: #222222;
  --border-light: #2a2a2a;
  --radius: 12px;
  --radius-lg: 16px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--fg);
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; color: inherit; }
ul { list-style: none; }
img { max-width: 100%; display: block; }

/* ─── Scrollbar ─── */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: #333; border-radius: 3px; }

/* ─── Navigation ─── */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 48px; height: 72px;
  background: rgba(10, 10, 10, 0.85); backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition);
}
.nav-logo {
  font-size: 20px; font-weight: 800; letter-spacing: -0.5px;
  display: flex; align-items: center; gap: 8px;
}
.nav-logo span { color: var(--accent); }
.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a {
  font-size: 14px; font-weight: 500; color: var(--fg-muted);
  transition: color var(--transition); position: relative;
}
.nav-links a:hover { color: var(--fg); }
.nav-links a::after {
  content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 1px;
  background: var(--accent); transition: width var(--transition);
}
.nav-links a:hover::after { width: 100%; }
.nav-right { display: flex; align-items: center; gap: 24px; }
.lang-selector { position: relative; }
.lang-btn {
  display: flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 500; color: var(--fg-muted);
  padding: 6px 12px; border-radius: 6px;
  transition: all var(--transition);
}
.lang-btn:hover { color: var(--fg); background: var(--bg-card); }
.lang-btn i { font-size: 16px; }
.lang-dropdown {
  position: absolute; top: calc(100% + 8px); right: 0;
  background: var(--bg-card); border: 1px solid var(--border-light);
  border-radius: var(--radius); padding: 6px; min-width: 160px;
  opacity: 0; visibility: hidden; transform: translateY(-8px);
  transition: all var(--transition); box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}
.lang-dropdown.active { opacity: 1; visibility: visible; transform: translateY(0); }
.lang-dropdown button {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px 14px; font-size: 13px; font-weight: 500;
  border-radius: 8px; transition: background var(--transition);
}
.lang-dropdown button:hover { background: var(--bg-card-hover); }
.lang-dropdown button.active { color: var(--accent); }
.lang-dropdown button i { font-size: 15px; }

/* Mobile nav */
.nav-hamburger { display: none; font-size: 24px; padding: 8px; color: var(--fg-muted); }
.mobile-menu {
  display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: var(--bg); z-index: 99; padding: 32px 24px;
  flex-direction: column; gap: 24px;
}
.mobile-menu.active { display: flex; }
.mobile-menu a {
  font-size: 24px; font-weight: 600; color: var(--fg-muted);
  padding: 12px 0; border-bottom: 1px solid var(--border);
  transition: color var(--transition);
}
.mobile-menu a:hover { color: var(--fg); }

@media (max-width: 1024px) {
  .nav { padding: 0 24px; }
  .nav-links { display: none; }
  .nav-hamburger { display: block; }
}

/* ─── Hero ─── */
.hero {
  position: relative; min-height: 100vh; display: flex; align-items: center;
  padding: 120px 48px 80px; overflow: hidden;
}
.hero-slides { position: relative; width: 100%; max-width: 1200px; margin: 0 auto; }
.hero-slide {
  display: none; opacity: 0;
  animation: heroIn 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.hero-slide.active { display: block; }
@keyframes heroIn { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }

.hero-tag {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 1.5px;
  color: var(--accent); margin-bottom: 24px;
}
.hero-tag i { font-size: 16px; }
.hero-title {
  font-size: clamp(36px, 5vw, 72px); font-weight: 800; line-height: 1.05;
  letter-spacing: -2px; margin-bottom: 24px; max-width: 800px;
}
.hero-desc {
  font-size: clamp(16px, 1.5vw, 20px); color: var(--fg-muted); max-width: 560px;
  line-height: 1.7; margin-bottom: 36px;
}
.hero-cta {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 15px; font-weight: 600; color: var(--accent);
  padding: 14px 28px; border: 1px solid var(--accent); border-radius: 100px;
  transition: all var(--transition);
}
.hero-cta:hover { background: var(--accent); color: var(--bg); }
.hero-cta i { font-size: 18px; transition: transform var(--transition); }
.hero-cta:hover i { transform: translateX(4px); }

.hero-controls {
  display: flex; align-items: center; gap: 16px; margin-top: 64px;
}
.hero-dot {
  width: 40px; height: 3px; background: var(--border-light); border-radius: 2px;
  transition: all var(--transition); cursor: pointer;
}
.hero-dot.active { width: 64px; background: var(--accent); }

.hero-arrows { display: flex; gap: 8px; margin-left: auto; }
.hero-arrow {
  width: 48px; height: 48px; border-radius: 50%;
  border: 1px solid var(--border-light); display: flex; align-items: center; justify-content: center;
  font-size: 20px; color: var(--fg-muted); transition: all var(--transition);
}
.hero-arrow:hover { border-color: var(--fg); color: var(--fg); }

/* Background gradient */
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 20% 50%, rgba(74, 158, 255, 0.06) 0%, transparent 60%),
              radial-gradient(ellipse at 80% 20%, rgba(232, 168, 56, 0.04) 0%, transparent 50%);
  pointer-events: none;
}

@media (max-width: 768px) {
  .hero { padding: 100px 20px 60px; }
  .hero-controls { gap: 10px; }
  .hero-arrows { margin-left: 0; margin-top: 16px; }
}

/* ─── Section Shared ─── */
.section { padding: 120px 48px; }
.section-header { max-width: 1200px; margin: 0 auto 64px; }
.section-label {
  font-size: 12px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 2px; color: var(--accent); margin-bottom: 16px;
}
.section-title {
  font-size: clamp(28px, 3.5vw, 48px); font-weight: 800;
  letter-spacing: -1px; line-height: 1.15; margin-bottom: 16px;
}
.section-subtitle {
  font-size: clamp(15px, 1.2vw, 18px); color: var(--fg-muted);
  max-width: 600px; line-height: 1.7;
}

@media (max-width: 768px) {
  .section { padding: 80px 20px; }
}

/* ─── Team Carousel ─── */
.team { background: var(--bg); }
.team-region-tabs {
  display: flex; gap: 4px; margin-bottom: 48px;
  max-width: 1200px; margin-left: auto; margin-right: auto;
  margin-bottom: 48px; padding: 4px; background: var(--bg-card);
  border-radius: 12px; width: fit-content;
}
.region-tab {
  padding: 12px 24px; font-size: 14px; font-weight: 600;
  border-radius: 8px; transition: all var(--transition);
  color: var(--fg-muted);
}
.region-tab:hover { color: var(--fg); }
.region-tab.active { background: var(--accent); color: var(--bg); }

.team-carousel-wrapper {
  max-width: 1200px; margin: 0 auto; position: relative;
}
.team-carousel {
  display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -ms-overflow-style: none; scrollbar-width: none;
  padding-bottom: 16px;
}
.team-carousel::-webkit-scrollbar { display: none; }

.team-card {
  min-width: 340px; max-width: 380px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition); flex-shrink: 0;
}
.team-card:hover { border-color: var(--border-light); transform: translateY(-4px); box-shadow: 0 20px 40px rgba(0,0,0,0.3); }
.team-card-photo {
  width: 100%; height: 280px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.team-card-photo .placeholder {
  font-size: 64px; color: var(--fg-dim);
}
.team-card-photo::after {
  content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 80px;
  background: linear-gradient(to top, var(--bg-card), transparent);
}
.team-card-body { padding: 24px; }
.team-card-name { font-size: 18px; font-weight: 700; margin-bottom: 4px; }
.team-card-title { font-size: 13px; color: var(--fg-muted); margin-bottom: 16px; }
.team-card-quote {
  font-size: 14px; color: var(--fg-muted); line-height: 1.7;
  font-style: italic; margin-bottom: 20px; padding-left: 16px;
  border-left: 2px solid var(--accent);
}
.team-card-cta {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 600; color: var(--accent);
  transition: gap var(--transition);
}
.team-card-cta:hover { gap: 10px; }

.team-nav { display: flex; gap: 8px; margin-top: 32px; justify-content: center; }
.team-nav-btn {
  width: 44px; height: 44px; border-radius: 50%;
  border: 1px solid var(--border-light); display: flex; align-items: center; justify-content: center;
  font-size: 18px; color: var(--fg-muted); transition: all var(--transition);
}
.team-nav-btn:hover { border-color: var(--fg); color: var(--fg); }

@media (max-width: 768px) {
  .team-card { min-width: 290px; }
  .team-region-tabs { flex-wrap: wrap; }
  .region-tab { padding: 10px 16px; font-size: 13px; }
}

/* ─── Work Showcase ─── */
.work { background: var(--bg); }
.work-carousel-wrapper {
  max-width: 1200px; margin: 0 auto; position: relative;
}
.work-carousel {
  display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory;
  scroll-behavior: smooth; -ms-overflow-style: none; scrollbar-width: none;
  padding-bottom: 16px;
}
.work-carousel::-webkit-scrollbar { display: none; }

.work-card {
  min-width: 360px; max-width: 420px; scroll-snap-align: start;
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition); flex-shrink: 0;
}
.work-card:hover { border-color: var(--border-light); transform: translateY(-4px); box-shadow: 0 20px 40px rgba(0,0,0,0.3); }
.work-card-img {
  width: 100%; height: 240px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden;
}
.work-card-img .placeholder { font-size: 48px; color: var(--fg-dim); }
.work-card-client {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--accent); margin-bottom: 8px;
}
.work-card-body { padding: 24px; }
.work-card-title { font-size: 18px; font-weight: 700; margin-bottom: 12px; line-height: 1.4; }
.work-card-quote {
  font-size: 13px; color: var(--fg-muted); line-height: 1.7;
  font-style: italic; margin-bottom: 8px;
}
.work-card-quote-author { font-size: 12px; color: var(--fg-dim); }
.work-card-cta {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 600; color: var(--accent);
  margin-top: 16px; transition: gap var(--transition);
}
.work-card-cta:hover { gap: 10px; }

.work-nav { display: flex; gap: 8px; margin-top: 32px; justify-content: center; }
.work-nav-btn {
  width: 44px; height: 44px; border-radius: 50%;
  border: 1px solid var(--border-light); display: flex; align-items: center; justify-content: center;
  font-size: 18px; color: var(--fg-muted); transition: all var(--transition);
}
.work-nav-btn:hover { border-color: var(--fg); color: var(--fg); }

@media (max-width: 768px) {
  .work-card { min-width: 300px; }
}

/* ─── CTA Banner ─── */
.cta-banner {
  padding: 120px 48px;
  background: linear-gradient(135deg, rgba(74, 158, 255, 0.08) 0%, rgba(232, 168, 56, 0.06) 100%);
  text-align: center;
}
.cta-banner-inner { max-width: 640px; margin: 0 auto; }
.cta-banner-title {
  font-size: clamp(28px, 3.5vw, 48px); font-weight: 800;
  letter-spacing: -1px; margin-bottom: 20px;
}
.cta-banner-text {
  font-size: clamp(15px, 1.2vw, 18px); color: var(--fg-muted);
  line-height: 1.7; margin-bottom: 36px;
}
.cta-banner-btn {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 15px; font-weight: 600;
  padding: 16px 36px; background: var(--fg); color: var(--bg);
  border-radius: 100px; transition: all var(--transition);
}
.cta-banner-btn:hover { transform: scale(1.04); box-shadow: 0 8px 32px rgba(255,255,255,0.15); }
.cta-banner-btn i { font-size: 18px; }

@media (max-width: 768px) {
  .cta-banner { padding: 80px 20px; }
}

/* ─── How We Work ─── */
.how-we-work {
  padding: 120px 48px;
}
.how-we-work-inner {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center;
}
.how-we-work-content {}
.how-we-work-visual {
  display: flex; align-items: center; justify-content: center;
  aspect-ratio: 4/3; border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--bg-card) 0%, rgba(74, 158, 255, 0.06) 100%);
  border: 1px solid var(--border);
}
.how-we-work-visual i { font-size: 120px; color: var(--fg-dim); opacity: 0.3; }
.how-we-work-title {
  font-size: clamp(28px, 3.5vw, 48px); font-weight: 800;
  letter-spacing: -1px; margin-bottom: 20px; line-height: 1.15;
}
.how-we-work-text {
  font-size: clamp(15px, 1.2vw, 18px); color: var(--fg-muted);
  line-height: 1.7; margin-bottom: 36px; max-width: 500px;
}
.how-we-work-cta {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 15px; font-weight: 600; color: var(--accent);
  padding: 14px 28px; border: 1px solid var(--accent); border-radius: 100px;
  transition: all var(--transition);
}
.how-we-work-cta:hover { background: var(--accent); color: var(--bg); }
.how-we-work-cta i { font-size: 18px; }

@media (max-width: 768px) {
  .how-we-work { padding: 80px 20px; }
  .how-we-work-inner { grid-template-columns: 1fr; gap: 40px; }
}

/* ─── Latest Insights ─── */
.insights { background: var(--bg); }
.insights-grid {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}
.insight-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition);
}
.insight-card:hover { border-color: var(--border-light); transform: translateY(-4px); box-shadow: 0 20px 40px rgba(0,0,0,0.3); }
.insight-card-img {
  width: 100%; height: 160px; background: #1a1a1a;
  display: flex; align-items: center; justify-content: center;
}
.insight-card-img i { font-size: 36px; color: var(--fg-dim); }
.insight-card-body { padding: 20px; }
.insight-card-type {
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--accent-warm); margin-bottom: 10px;
  display: flex; align-items: center; gap: 6px;
}
.insight-card-type i { font-size: 14px; }
.insight-card-title { font-size: 16px; font-weight: 700; line-height: 1.4; margin-bottom: 16px; }
.insight-card-cta {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 600; color: var(--accent);
  transition: gap var(--transition);
}
.insight-card-cta:hover { gap: 10px; }

@media (max-width: 768px) {
  .insights-grid { grid-template-columns: 1fr; }
}

/* ─── Principles ─── */
.principles { padding: 120px 48px; }
.principles-grid {
  max-width: 1200px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px;
}
.principle-card {
  padding: 40px; background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); transition: all var(--transition);
  position: relative; overflow: hidden;
}
.principle-card:hover { border-color: var(--accent); transform: translateY(-4px); }
.principle-card::before {
  content: ''; position: absolute; top: 0; left: 0; width: 3px; height: 0;
  background: var(--accent); transition: height 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}
.principle-card:hover::before { height: 100%; }
.principle-number {
  font-size: 12px; font-weight: 700; color: var(--accent);
  letter-spacing: 2px; margin-bottom: 16px;
}
.principle-title {
  font-size: 20px; font-weight: 700; margin-bottom: 12px; line-height: 1.3;
}
.principle-desc {
  font-size: 14px; color: var(--fg-muted); line-height: 1.7;
}

@media (max-width: 768px) {
  .principles { padding: 80px 20px; }
  .principles-grid { grid-template-columns: 1fr; }
}

/* ─── Footer ─── */
.footer { padding: 80px 48px 40px; border-top: 1px solid var(--border); }
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-ctas {
  display: grid; grid-template-columns: 1fr 1fr; gap: 40px;
  margin-bottom: 64px;
}
.footer-cta-block {}
.footer-cta-text {
  font-size: clamp(14px, 1.1vw, 16px); color: var(--fg-muted);
  line-height: 1.7; margin-bottom: 20px;
}
.footer-cta-link {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 15px; font-weight: 600; color: var(--accent);
  transition: gap var(--transition);
}
.footer-cta-link:hover { gap: 12px; }

.footer-links-row {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 16px; padding: 32px 0;
  border-top: 1px solid var(--border);
}
.footer-links { display: flex; gap: 24px; }
.footer-links a {
  font-size: 13px; font-weight: 500; color: var(--fg-muted);
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--fg); }

.footer-legal {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 16px; padding: 24px 0;
  font-size: 12px; color: var(--fg-dim);
}
.footer-legal-links { display: flex; gap: 20px; }
.footer-legal-links a { color: var(--fg-dim); transition: color var(--transition); }
.footer-legal-links a:hover { color: var(--fg-muted); }

@media (max-width: 768px) {
  .footer { padding: 60px 20px 30px; }
  .footer-ctas { grid-template-columns: 1fr; }
  .footer-links-row { flex-direction: column; align-items: flex-start; }
  .footer-legal { flex-direction: column; align-items: flex-start; }
}

/* ─── Cookie Consent ─── */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--bg-card); border-top: 1px solid var(--border);
  padding: 20px 48px; display: flex; align-items: center; justify-content: space-between;
  gap: 24px; transform: translateY(100%); transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-text { font-size: 13px; color: var(--fg-muted); line-height: 1.6; flex: 1; }
.cookie-text a { color: var(--accent); }
.cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
.cookie-btn {
  padding: 10px 20px; font-size: 13px; font-weight: 600;
  border-radius: 8px; transition: all var(--transition);
}
.cookie-btn-accept { background: var(--accent); color: var(--bg); }
.cookie-btn-accept:hover { opacity: 0.9; }
.cookie-btn-manage { border: 1px solid var(--border-light); color: var(--fg-muted); }
.cookie-btn-manage:hover { border-color: var(--fg-muted); color: var(--fg); }
